import{icon,knot,sprig}from'./hud-icons.js';
import{createHudMap}from'./hud-map.js';
import{createHudEditor}from'./hud-editor.js';
import{asset}from'./materials.js';
function gestureBody(index){const points=Array.from({length:10},(_,i)=>{const a=Math.PI/2-i*Math.PI/5,r=i%2?13:26;return{x:30+Math.cos(a)*r,y:30-Math.sin(a)*r}});let d='';for(let i=0;i<10;i++){const p=points[i],prev=points[(i+9)%10],next=points[(i+1)%10],a={x:p.x+(prev.x-p.x)*.17,y:p.y+(prev.y-p.y)*.17},b={x:p.x+(next.x-p.x)*.17,y:p.y+(next.y-p.y)*.17};d+=(i?'L':'M')+a.x+' '+a.y+'Q'+p.x+' '+p.y+' '+b.x+' '+b.y}const id='hudStarGold'+index;return '<defs><radialGradient id="'+id+'" cx="35%" cy="20%" r="80%"><stop stop-color="#fff0a6"/><stop offset=".65" stop-color="#edc355"/><stop offset="1" stop-color="#d7a340"/></radialGradient></defs><path d="'+d+'Z" fill="url(#'+id+')" stroke="#b78635" stroke-width="1.2"/>'+ (index===4?'<path d="M21 29q3-3 6 0m6 0q3-3 6 0" stroke="#573e2b"/>':'<g fill="#503d2a" stroke="none"><ellipse cx="24" cy="29" rx="2" ry="2.7"/><ellipse cx="36" cy="29" rx="2" ry="2.7"/></g><g fill="#fff1d3" stroke="none"><circle cx="23.5" cy="28" r=".65"/><circle cx="35.5" cy="28" r=".65"/></g>')+'<g fill="#d99073" stroke="none" opacity=".8"><ellipse cx="20" cy="35" rx="3" ry="1.3"/><ellipse cx="40" cy="35" rx="3" ry="1.3"/></g>'+([0,2,4].includes(index)?'<path d="M26 37q4 5 8 0" stroke="#68452a" stroke-width="1.7"/>':'')}
export function createHud({MAP,world,player,camera,state,resetInput,playGesture}){
 const $=s=>document.querySelector(s),tools=$('.tools'),controls=$('#controlSettings');document.body.append(controls);controls.classList.add('ui');controls.innerHTML=icon('settings')+'<span>設定</span>';controls.title='介面位置・大小・透明度 · U';
 $('.brand')?.remove();$('#rescue')?.remove();$('#intro').hidden=true;
 const seasons=$('.seasons'),seasonPanel=document.createElement('section');seasonPanel.id='hudSeasons';seasonPanel.className='hud-panel';seasonPanel.hidden=true;seasonPanel.innerHTML='<h3>季節設定</h3>';seasonPanel.append(seasons);document.body.append(seasonPanel);document.querySelector('body>header')?.remove();for(const b of seasons.querySelectorAll('button'))b.innerHTML=icon(b.dataset.season)+'<span>'+({spring:'春',summer:'夏',autumn:'秋',winter:'冬'}[b.dataset.season])+'</span>';
 const seasonButton=document.createElement('button');seasonButton.id='seasonControl';seasonButton.setAttribute('aria-label','四季選擇');seasonButton.setAttribute('aria-expanded','false');seasonButton.innerHTML=icon('season')+'<span>季節</span>';tools.insertBefore(seasonButton,$('#weather'));
 function closeSeason(){seasonPanel.hidden=true;seasonButton.setAttribute('aria-expanded','false')}
 seasonButton.onclick=()=>{const show=seasonPanel.hidden;closeSeason();if(!show)return;resetInput();seasonPanel.hidden=false;seasonButton.setAttribute('aria-expanded','true');const r=seasonButton.getBoundingClientRect();seasonPanel.style.left=Math.max(12,Math.min(innerWidth-288,r.left-286))+'px';seasonPanel.style.top=Math.max(12,Math.min(innerHeight-130,r.top-20))+'px'};
 for(const b of seasons.querySelectorAll('button'))b.addEventListener('click',closeSeason);document.addEventListener('pointerdown',e=>{if(!seasonPanel.contains(e.target)&&!seasonButton.contains(e.target))closeSeason()});addEventListener('resize',closeSeason);
 const toolIcons={overview:'torii',photo:'camera',map:'map',album:'book',light:'sun',weather:'weather',sound:'music',quality:'quality',fullscreen:'full',help:'help'};for(const[id,name]of Object.entries(toolIcons)){const b=$('#'+id),label=b.querySelector('span').outerHTML;b.innerHTML=icon(name)+label}
 const mini=document.createElement('figure');mini.id='hudMinimap';mini.className='ui';mini.innerHTML='<div class="map-ring"><canvas aria-label="依實際參道路線繪製的即時位置小地圖"></canvas><b class="map-north">N</b><button data-map-zoom="in" aria-label="放大小地圖">+</button><button data-map-zoom="out" aria-label="縮小小地圖">−</button>'+knot()+'</div><figcaption>伏見稻荷</figcaption>';document.body.append(mini);mini.querySelector('canvas').onclick=()=>$('#map').click();const map=createHudMap({container:mini,MAP,player,camera,world});
 $('#journey').innerHTML=icon('book')+'<span>參拜手帖</span>';$('#touchPhoto').innerHTML=icon('camera')+'<span>拍照</span>';
 const actions=document.createElement('nav');actions.id='hudActions';actions.className='ui';actions.setAttribute('aria-label','小星星散步動作');actions.innerHTML='<span class="hud-strip-tag">小星星</span>'+[['wave','揮手','Z'],['jump','跳一下','Space'],['think','想一想','X'],['surprise','驚喜','F'],['rest','歇一歇','T'],['reward','慶祝','G']].map(([id,label,key],i)=>'<button data-hud-gesture="'+id+'" title="'+label+' · '+key+'" aria-label="'+label+'"><svg class="gesture-icon" viewBox="0 0 60 60" aria-hidden="true">'+gestureBody(i)+''+(['<path d="M42 32q18-18 12-24m-3 0 5-2m-4 6 6 0"/>','<path d="M15 53l-5 4m35-4 5 4M25 37q5 6 10 0"/>','<path d="M32 38l10 5m-5-29q10-12 15-1 0 6-6 7"/>','<ellipse cx="30" cy="38" rx="3" ry="5"/><path d="M50 7v9m0 4v1"/>','<path d="M21 29l5-1m8 0 5 1M44 9h9l-9 10h9m-2-17h5l-5 5h5"/>','<path d="M24 37q6 7 12 0M46 7l3 5 6 1-4 4 1 5-5-2-4 3 1-6-4-3 6-1z"/>'][i])+'</svg><small>'+label+'</small></button>').join('');document.body.append(actions);for(const b of actions.querySelectorAll('button'))b.onclick=()=>playGesture(b.dataset.hudGesture);
 const destinations=$('#destinations');destinations.insertAdjacentHTML('afterbegin','<b class="hud-route-title">'+icon('torii')+'<span>快速傳送</span></b>'+knot());for(const button of destinations.querySelectorAll('[data-place]')){const label=button.textContent.replace(/^\d+ /,'');button.textContent='';const img=document.createElement('img');img.alt='';img.width=128;img.height=72;img.src=asset('v3.6/route-'+button.dataset.place+'.webp');button.append(img,document.createElement('span'));button.lastElementChild.textContent=label}
 const fromRight=(width,gap)=>Math.max(0,100-gap/Math.max(1,innerWidth-24-width)*100),fromBottom=(height,gap)=>Math.max(0,100-gap/Math.max(1,innerHeight-24-height)*100),short=()=>innerHeight<560;
 const defaults={tools:p=>({x:100,y:short()?80:p==='compact'?33.64:57,scale:100,opacity:100}),minimap:p=>({x:p==='compact'?80:91,y:0,scale:100,opacity:100}),location:()=>({x:0,y:2,scale:100,opacity:100}),routes:()=>({x:50,y:100,scale:100,opacity:100}),actions:p=>({x:50,y:fromBottom(p==='compact'?57:79,p==='compact'?(short()?93:226):151),scale:100,opacity:100}),joystick:p=>({x:1,y:p==='compact'?fromBottom(94,short()?46:119):84,scale:100,opacity:100}),journal:p=>({x:fromRight(p==='compact'?64:76,p==='compact'?(short()?137:76):162),y:fromBottom(p==='compact'?64:76,p==='compact'?(short()?86:134):152),scale:100,opacity:100}),photo:p=>({x:fromRight(p==='compact'?64:76,p==='compact'?(short()?61:0):74),y:fromBottom(p==='compact'?64:76,p==='compact'?(short()?86:134):152),scale:100,opacity:100}),hint:()=>({x:50,y:92,scale:100,opacity:80}),start:()=>({x:50,y:70,scale:100,opacity:100})};
 const ids={tools:'.tools',minimap:'#hudMinimap',location:'#location',routes:'#destinations',actions:'#hudActions',joystick:'#joystick',journal:'#journey',photo:'#touchPhoto',hint:'#walkHint',start:'#startWrap'},names={tools:'右側工具列',minimap:'即時小地圖',location:'目前位置',routes:'快速傳送',actions:'小星星動作列',joystick:'移動搖桿',journal:'參拜手帖按鈕',photo:'拍照按鈕',hint:'鍵盤操作提示',start:'開始散步按鈕'};
 const recovery=$('#unstuck');document.body.append(recovery);recovery.classList.add('ui');const context=document.createElement('div');context.id='hudContext';context.className='ui';document.body.append(context);for(const id of ['siteAction','pray','teaBreak'])context.append($('#'+id));
 Object.assign(ids,{recovery:'#unstuck',context:'#hudContext',progress:'#ritualProgress'});Object.assign(names,{recovery:'回到參道按鈕',context:'景點與參拜體驗',progress:'體驗進度提示'});Object.assign(defaults,{recovery:p=>({x:p==='compact'?1:12,y:p==='compact'?fromBottom(30,short()?0:78):84,scale:100,opacity:100}),context:p=>({x:50,y:fromBottom(context.offsetHeight||40,p==='compact'?(short()?166:299):246),scale:100,opacity:100}),progress:p=>({x:50,y:p==='compact'?20:18,scale:100,opacity:100})});
 destinations.insertAdjacentHTML('beforeend',sprig());mini.querySelector('.map-ring').insertAdjacentHTML('beforeend',sprig());
 const editor=createHudEditor({resetInput,widgets:Object.entries(ids).map(([id,selector])=>({id,name:names[id],element:$(selector),defaults:defaults[id]}))});
 let previousMode=null;
 return{editor,map,update(time,mode){map.update(time);actions.hidden=mode!=='walk';recovery.hidden=mode!=='walk';mini.hidden=mode==='photo';if(state.season)seasonButton.dataset.season=state.season;const signature=[mode,context.textContent,...Array.from(context.children,x=>x.hidden),$('#ritualProgress').hidden].join(':');if(signature!==previousMode){previousMode=signature;editor.apply()}},get editing(){return editor.editing}};
}
